# Exact MLX head payload test-artifact cleanup. No recursive directory removal.
$ErrorActionPreference = 'Stop'
$plan = Get-Content -LiteralPath 'C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\mlx-head-payload-2026-10-21\root\cleanup-plan.json' -Raw | ConvertFrom-Json
$separator = [IO.Path]::DirectorySeparatorChar
$allowed = [IO.Path]::GetFullPath($plan.allowed_windows).TrimEnd($separator) + $separator
function Assert-Identity($row) {
  $file = Get-Item -LiteralPath $row.path -ErrorAction Stop
  if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Not a regular file: $($row.path)" }
  if ($file.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Identity changed: $($row.path)" }
}
Assert-Identity $plan.evidence
Assert-Identity $plan.archive
foreach ($row in $plan.remove_windows) {
  $full = [IO.Path]::GetFullPath($row.path)
  if (-not $full.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -notin '.exe','.map') { throw "Outside exact artifact scope: $full" }
  Assert-Identity $row
}
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
$active = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) })
if ($active.Count) { throw 'A test executable in this exact workspace is still running' }
foreach ($row in $plan.remove_windows) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
$macProgram = @'
import pathlib,hashlib,json,subprocess
plan=json.loads('{"allowed_mac": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple", "remove_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/mlx-head-payload", "bytes": 17206000, "sha256": "a6409486d2c80b2bcc08ee0fbd2da69a9efb632dcef2149b0b37c2ffe7476a0f"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/mlx-head-payload.map", "bytes": 5107088, "sha256": "e96ab67599a428d590dd3e53bad01e0d7bfd8469aaeefec4a0717396c11aa0fd"}], "keep_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/objects/src--compute_route_apple--apple_memory.mm.o", "bytes": 126288, "sha256": "bbcb3ca3b17ad43c88ff4618c8626b6a7d41809e0a2cb4ea3fe87732eaf49ae7"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/objects/src--graph_route_apple--native_region.cc.o", "bytes": 192600, "sha256": "6a3482f566290e44ae856243d757c5f4603e627dad20be286daf7555905f1dba"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/objects/tests--graph_route_apple--mlx_head_payload_test.cc.o", "bytes": 229088, "sha256": "e04f162897b91e73eab6069624c4e20d3d90ed91cc9c109e527bac8d3580e9b1"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/mlx-head-payload-2026-10-21/apple/objects/tests--graph_route_apple--native_region_test.cc.o", "bytes": 319752, "sha256": "b73658b903ff0ca938cb64b7a4c9a3f7b4536d91ecb4992fc13e282b656cc851"}]}')
base=pathlib.Path(plan['allowed_mac']); assert base.is_dir() and not base.is_symlink()
def verify(row):
 p=pathlib.Path(row['path']); assert p.is_absolute() and not p.is_symlink() and p.resolve().is_relative_to(base.resolve())
 assert p.is_file() and p.stat().st_size==row['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==row['sha256'],str(p)
 return p
paths=[verify(x) for x in plan['remove_mac']]
for row in plan['keep_mac']:verify(row)
active=subprocess.check_output(['ps','-axo','command='],text=True)
assert not any(str(p) in command for p in paths for command in active.splitlines() if not command.startswith('python3 -')), 'test executable is running'
for p in paths:p.unlink()
for row in plan['keep_mac']:verify(row)
print(json.dumps(dict(removed=len(paths),bytes=sum(x['bytes'] for x in plan['remove_mac']),kept_objects=len(plan['keep_mac']))))
'@
$macResult = $macProgram | & ssh kiro@172.22.10.198 python3 -
if ($LASTEXITCODE -ne 0) { throw 'Mac exact-file cleanup failed; do not report both platforms completed' }
$result = [ordered]@{
  completed = $true
  windows_removed = @($plan.remove_windows).Count
  windows_bytes = ($plan.remove_windows | Measure-Object -Property bytes -Sum).Sum
  windows_kept_objects = @($plan.keep_windows).Count
  mac = ($macResult | ConvertFrom-Json)
  evidence_sha256 = $plan.evidence.sha256
  archive_sha256 = $plan.archive.sha256
  exact_plan = $plan
  source_script = [IO.File]::ReadAllText($PSCommandPath)
}
$result | ConvertTo-Json -Depth 18 | Set-Content -LiteralPath 'C:\public\project-hyle\hyle\docs\evidence\correctness\mlx-head-payload-reference-2026-10-21.cleanup.json' -Encoding utf8
[pscustomobject]$result | Select-Object completed,windows_removed,windows_bytes,windows_kept_objects,mac | ConvertTo-Json -Depth 5
